from pathlib import Path
import yaml
issues=[]
for file in Path('.planning/phases/99-solo-mode-desk-optional').glob('99-*-PLAN.md'):
    meta=yaml.safe_load(file.read_text().split('---',2)[1])
    for group in ['truths','artifacts','key_links']:
        for i,item in enumerate(meta['must_haves'][group]):
            if not isinstance(item,str):
                issues.append(f'{file}: must_haves.{group}[{i}] is {type(item).__name__}, must be string')
print('\n'.join(issues) if issues else 'PASS: GSD must_haves values are strings')
raise SystemExit(bool(issues))
